use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn f(n: int) -> int
    recommends n >= 2
{
    if n >= 4 {
        n % 2
    } else {
        4 - n
    }
}

fn solve(queries: Vec<i8>) -> (results: Vec<i8>)
    requires
        forall |i: int| 0 <= i && i < queries.len() ==> queries[i] as int >= 2,
    ensures
        results.len() == queries.len(),
        forall |i: int| 0 <= i && i < queries.len() ==> 
            results[i] as int == f(queries[i] as int),
{
    let mut results_vec = Vec::new();
    let mut idx: usize = 0;
    
    while idx < queries.len()
        invariant
            0 <= idx <= queries.len(),
            results_vec.len() == idx,
            forall |i: int| 0 <= i && i < idx ==> 
                results_vec[i] as int == f(queries[i] as int),
    {
        let query = queries[idx];
        
        // The precondition ensures query >= 2, so we don't need to check for negative values
        let result = if query >= 4 {
            // For i8, n % 2 gives 0 for even, 1 for positive odd, -1 for negative odd
            // But since query >= 4, it's positive, so result will be 0 or 1
            query % 2
        } else {
            // query is 2 or 3 (since query >= 2 and < 4)
            4 - query
        };
        
        results_vec.push(result);
        idx = idx + 1;
    }
    
    results_vec
}

}